import numpy as np
from scipy.integrate import quad
coef=[0.42,-1.1,0.7,0.35]   # 与上脚本同 seed 重构不重要, 任取连续 g
gf=np.polynomial.polynomial.Polynomial(coef)
A=float(gf.integ()(1)); print("A=",A)
try:
    for beta in [0.35,0.7]:
        for u0 in [1e-2,1e-3]:
            p1=quad(lambda tt:(u0-tt)**(beta-1)*float(gf(tt)),0,u0,limit=500)[0]
            p2=quad(lambda tt:(tt-u0)**(beta-1)*float(gf(tt)),u0,1,limit=500)[0]
            F=p1-p2
            print(f"beta={beta} u={u0:.0e}: F(u)={F:+.4e}  F*u^(1-beta)={F*u**(1-beta):+.4e}")
except Exception as e:
    import traceback; traceback.print_exc()
EOF

